describe('Filter List by Multiple Statuses', () => {
  beforeEach(() => {
    cy.visit('/list');
  });

  it('should filter list by multiple statuses simultaneously and display matching items', () => {
    // Setup: Load initial list with multiple items
    cy.get('[data-testid="list-item"]').should('have.length.greaterThan', 0);

    // Intercept API call to get list items
    cy.intercept('GET', '/api/items').as('getItems');
    cy.wait('@getItems');

    // Verify initial list is displayed
    cy.get('[data-testid="list-item"]').should('have.length.greaterThan', 0);

    // Click filter button
    cy.get('[data-testid="filter-button"]').click();

    // Verify filter dropdown appears
    cy.get('[data-testid="filter-dropdown"]').should('be.visible');

    // Select multiple statuses from dropdown
    cy.get('[data-testid="filter-dropdown"]').select('Completed');
    cy.get('[data-testid="filter-dropdown"]').select('In Progress');

    // Verify filter is applied
    cy.get('[data-testid="filter-dropdown"]').should('contain', 'Completed');
    cy.get('[data-testid="filter-dropdown"]').should('contain', 'In Progress');

    // Verify filtered items are displayed
    cy.get('[data-testid="list-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="list-item"]').should('contain', 'Completed');
    cy.get('[data-testid="list-item"]').should('contain', 'In Progress');

    // Verify no items are displayed for excluded statuses
    cy.get('[data-testid="list-item"]').should('not.contain', 'Cancelled');

    // Verify filter button is still visible
    cy.get('[data-testid="filter-button"]').should('be.visible');
  });

  it('should handle edge case where no items match the filter criteria', () => {
    // Setup: Load initial list with no matching items
    cy.intercept('GET', '/api/items').as('getItems');
    cy.wait('@getItems');

    // Verify initial list is displayed
    cy.get('[data-testid="list-item"]').should('have.length.greaterThan', 0);

    // Click filter button
    cy.get('[data-testid="filter-button"]').click();

    // Verify filter dropdown appears
    cy.get('[data-testid="filter-dropdown"]').should('be.visible');

    // Select multiple statuses from dropdown
    cy.get('[data-testid="filter-dropdown"]').select('Completed');
    cy.get('[data-testid="filter-dropdown"]').select('In Progress');

    // Verify filter is applied
    cy.get('[data-testid="filter-dropdown"]').should('contain', 'Completed');
    cy.get('[data-testid="filter-dropdown"]').should('contain', 'In Progress');

    // Verify no items are displayed
    cy.get('[data-testid="list-item"]').should('have.length.equal', 0);

    // Verify filter button still exists
    cy.get('[data-testid="filter-button"]').should('be.visible');

    // Verify no error message is displayed
    cy.get('[data-testid="no-results-message"]').should('not.exist');
  });
});
